// Differential checks of InlineDemo-pbo.js against Lean, generated by leanscript --check
import * as M from "./InlineDemo-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("foo(0, 0)", () => M.foo(0, 0), "0", false);
check("foo(0, 2)", () => M.foo(0, 2), "0", false);
check("foo(1, 1)", () => M.foo(1, 1), "2", false);
check("foo(2, 0)", () => M.foo(2, 0), "2", false);
check("foo(0, 13)", () => M.foo(0, 13), "0", false);
check("foo(1, 5)", () => M.foo(1, 5), "6", false);
check("foo(2, 2)", () => M.foo(2, 2), "6", false);
check("foo(5, 1)", () => M.foo(5, 1), "10", false);
check("foo(13, 0)", () => M.foo(13, 0), "13", false);
check("foo(2, 13)", () => M.foo(2, 13), "28", false);
check("foo(5, 5)", () => M.foo(5, 5), "30", false);
check("foo(13, 2)", () => M.foo(13, 2), "39", false);
check("foo(13, 13)", () => M.foo(13, 13), "182", false);
check("bar()", () => M.bar(), "3", false);
check("useScale(0)", () => M.useScale(0), "2", false);
check("useScale(1)", () => M.useScale(1), "6", false);
check("useScale(2)", () => M.useScale(2), "10", false);
check("useScale(5)", () => M.useScale(5), "22", false);
check("useScale(13)", () => M.useScale(13), "54", false);
check("triple(0)", () => M.triple(0), "0", false);
check("triple(1)", () => M.triple(1), "3", false);
check("triple(2)", () => M.triple(2), "6", false);
check("triple(5)", () => M.triple(5), "15", false);
check("triple(13)", () => M.triple(13), "39", false);
check("useTriple(0)", () => M.useTriple(0), "3", false);
check("useTriple(1)", () => M.useTriple(1), "9", false);
check("useTriple(2)", () => M.useTriple(2), "15", false);
check("useTriple(5)", () => M.useTriple(5), "33", false);
check("useTriple(13)", () => M.useTriple(13), "81", false);

console.log(`InlineDemo-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
